# Das Artefakt

```jsx
import { useOptimistic, useRef } from "react";
import { useFormStatus } from "react-dom";

function SendeKnopf() {
  const { pending } = useFormStatus();
  return <button disabled={pending}>{pending ? "Sende ..." : "Abschicken"}</button>;
}

export function Kommentare({ kommentare, sendeKommentar }) {
  const formular = useRef(null);
  const [anzeige, fuegeOptimistischHinzu] = useOptimistic(
    kommentare,
    (bisher, neuerText) => [...bisher, { id: "temp", text: neuerText, schwebend: true }]
  );

  return (
    <>
      <ul>
        {anzeige.map((k) => (
          <li key={k.id} style={{ opacity: k.schwebend ? 0.5 : 1 }}>{k.text}</li>
        ))}
      </ul>
      <form
        ref={formular}
        action={async (formData) => {
          const text = formData.get("text");
          fuegeOptimistischHinzu(text);
          formular.current.reset();
          await sendeKommentar(text);
        }}
      >
        <input name="text" />
        <SendeKnopf />
      </form>
    </>
  );
}
```

Drei Details, die die Uebungen aufgreifen: der Absendeknopf ist ein **eigenes Bauteil**, der Reduzierer baut ein **neues Array**, und `formular.current.reset()` leert das Feld, bevor das Netz antwortet.

